<script setup lang="ts">
import{qualityInventoryEntry,qualityExpenseEntry,qualityRecordEntry,qualitySourceEntry,qualitySourceGuide,type QualitySourceEntry}from'./quality-source-entry';
import{qualityCommand,parseQualityCommand,validQualitySaved}from'./quality-command';
import QualityRecovery from'./QualityRecovery.vue';import{sameQualityPending}from'./quality-pending-status';
import{ref,onMounted,computed,watch}from'vue';import{useSalesScope}from'./use-sales-scope';import{Search,ArrowLeft,X,Plus,ClipboardCheck}from'@lucide/vue';
const props=defineProps<{staff:any;returnEntry?:QualitySourceEntry|null}>(),emit=defineEmits(['unauthorized','open-inventory-source','open-expense-source','open-record-source','return-consumed']);
const sourceGuide=computed(()=>qualitySourceGuide(detail.value?.source?.kind));
function openOriginalSource(){if(busy.value||pending.value||mode.value||!props.staff.functions?.includes('stock.read')||detail.value?.source?.kind!=='issue')return;try{emit('open-inventory-source',qualityInventoryEntry({kind:'issue',issueId:detail.value.source.id,clinicId:detail.value.source.clinic,qualityIssueId:detail.value.issue.issue_id,version:detail.value.source.version,year:year.value,quarter:quarter.value}));}catch(e){error.value=explain(e);}}
function openOriginalExpense(){if(busy.value||pending.value||mode.value||!props.staff.functions?.includes('expense.manage')||detail.value?.source?.kind!=='expense')return;try{emit('open-expense-source',qualityExpenseEntry({kind:'expense',expenseId:detail.value.source.id,clinicId:detail.value.source.clinic,qualityIssueId:detail.value.issue.issue_id,version:detail.value.source.version,year:year.value,quarter:quarter.value}));}catch(e){error.value=explain(e);}}
function openOriginalRecord(){if(busy.value||loading.value||pending.value||mode.value||!props.staff.functions?.includes('clinical.read')||detail.value?.source?.kind!=='record')return;try{emit('open-record-source',qualityRecordEntry({kind:'record',recordId:detail.value.source.id,clinicId:detail.value.source.clinic,qualityIssueId:detail.value.issue.issue_id,version:detail.value.source.version,year:year.value,quarter:quarter.value}));}catch(e){error.value=explain(e);}}
const clinics=ref<any[]>([]),clinic=ref(''),year=ref(new Date().getFullYear()),quarter=ref(Math.floor(new Date().getMonth()/3)+1),kinds=ref(['expense','issue','record']),items=ref<any[]>([]),next=ref<string|null>(null),detail=ref<any>(null),preview=ref<any>(null),mode=ref(''),form=ref<any>({}),pending=ref<any>(null),source=ref<any>(null),busy=ref(false),loading=ref(false),error=ref(''),notice=ref(''),cacheBlocked=ref(false);
const listTotal=ref<number|null>(null),listAsOf=ref(''),historyItems=ref<any[]>([]),historyTotal=ref<number|null>(null),historyNext=ref<string|null>(null),historyAsOf=ref(''),historyLoading=ref(false);
const sourceTerm=ref(''),sourceChoices=ref<any[]>([]),sourceTotal=ref<number|null>(null),sourceNext=ref<string|null>(null),sourceAsOf=ref(''),sourceLoading=ref(false),sourceChoiceEpoch=ref(0);
function clearSourceChoices(){sourceChoiceEpoch.value++;sourceChoices.value=[];sourceTotal.value=null;sourceNext.value=null;sourceAsOf.value='';sourceLoading.value=false;}
function sourceChoiceSignature(){return JSON.stringify([mode.value,form.value.sourceKind,sourceTerm.value,sourceChoiceEpoch.value]);}
function clearList(){items.value=[];next.value=null;listTotal.value=null;listAsOf.value='';}
const manageClinicIds=ref<string[]>([]),canManage=computed(()=>manageClinicIds.value.includes(clinic.value));
const names:Record<string,string>={expense:'费用凭据与待补',issue:'领用成本',record:'病历完整状态'},states:Record<string,string>={open:'未解决',corrected:'已核实补正',justified_blank:'已核实合理空项'},actions:Record<string,string>={detect:'检查发现',reopen:'再次发现',manual:'人工核查',assign:'调整责任岗位',notify:'实际通知',handle:'处理经过',recheck:'复查'};
const short=(s:string)=>s?.slice(0,8).toUpperCase(),full=(s:string)=>new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}),roles=['前台','医生','护士','物资管理人员','财务人员','诊所管理人员'];
const identity=()=>JSON.stringify([props.staff.accountId,props.staff.employeeId]),epoch=ref(0),choice=ref(0),formEpoch=ref(0),scanEpoch=ref(0),sourceEpoch=ref(0),selected=ref(''),authScope=useSalesScope(identity),viewScope=useSalesScope(()=>JSON.stringify([identity(),clinic.value,year.value,quarter.value,epoch.value]));
const key=()=> 'adc.qualityPending:'+props.staff.accountId,copy=(v:any)=>JSON.parse(JSON.stringify(v)),explain=(e:any)=>e instanceof Error?e.message:'操作失败。';
const filters=()=>({clinicId:clinic.value,year:year.value,quarter:quarter.value}),scanSignature=()=>JSON.stringify({...filters(),kinds:kinds.value,scanEpoch:scanEpoch.value}),sourceSignature=()=>JSON.stringify([mode.value,form.value.sourceKind,form.value.sourceId,sourceEpoch.value]);
function clearView(){clearList();clearHistory();clearSourceChoices();sourceTerm.value='';epoch.value++;choice.value++;selected.value='';items.value=[];next.value=null;detail.value=null;preview.value=null;source.value=null;mode.value='';form.value={};busy.value=false;loading.value=false;notice.value='';}
watch(()=>JSON.stringify(filters()),()=>{clearView();error.value='';},{flush:'sync'});
watch(()=>JSON.stringify(kinds.value),()=>{scanEpoch.value++;preview.value=null;},{flush:'sync'});
watch(()=>JSON.stringify(Object.fromEntries(Object.entries(form.value).filter(([k])=>k!=='actualChecked'))),()=>{formEpoch.value++;form.value.actualChecked=false;},{flush:'sync'});
watch(()=>JSON.stringify([form.value.sourceKind,form.value.sourceId]),()=>{sourceEpoch.value++;source.value=null;},{flush:'sync'});
watch(()=>JSON.stringify([form.value.sourceKind,sourceTerm.value]),()=>{clearSourceChoices();if(mode.value==='manual'){form.value.sourceId='';source.value=null;form.value.note='';}},{flush:'sync'});
function loseAccess(){clearView();manageClinicIds.value=[];clinics.value=[];}
class ApiError extends Error{constructor(public status:number,m:string){super(m);}}
async function api(path:string,body?:any,current:()=>boolean=()=>true){const own=authScope.capture(),abort=new AbortController(),timer=setTimeout(()=>abort.abort(),15000);try{const r=await fetch('/api/v1/quality'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:abort.signal}),b=await r.json().catch(()=>({}));if(!own()||!current())throw Error('原资料检查上下文已变化。');if(!r.ok){if([401,403].includes(r.status)){loseAccess();error.value=b.message||'当前资料检查读取权限已失效。';if(r.status===401)emit('unauthorized');}throw new ApiError(r.status,b.message||'请求失败。');}return b;}finally{clearTimeout(timer);}}
function adoptedVersion(a:any){try{const b=JSON.parse(a.source_basis||'null');return b?.source?.version||b?.version||b?.sourceVersion||null;}catch{return null;}}
const cacheRaw=ref<string|null>(null),cacheIdentity=ref(''),cacheError=ref(''),owner=()=>({accountId:props.staff.accountId,employeeId:props.staff.employeeId});
function restoreCache(){notice.value='';const known=cacheIdentity.value===identity()&&['confirmed','rejected'].includes(pending.value?.phase)?pending.value:null;pending.value=null;cacheBlocked.value=false;cacheError.value='';cacheIdentity.value=identity();try{const raw=sessionStorage.getItem(key());cacheRaw.value=raw;if(raw){const p=parseQualityCommand(raw,owner());pending.value=known&&sameQualityPending(known,p)?known:p;}else pending.value=known;}catch{cacheBlocked.value=true;pending.value=known;cacheError.value='原资料检查记录损坏、身份不符或无法读取；已保留记录并阻止新办理。';}}
function readOriginal(){if(cacheBlocked.value||cacheIdentity.value!==identity())throw Error('原记录待核查，未覆盖或删除。');let raw:string|null;try{raw=sessionStorage.getItem(key());}catch{cacheBlocked.value=true;throw Error('无法读取原本机记录，未发送。');}if(raw!==cacheRaw.value){cacheBlocked.value=true;throw Error('本机已换入另一笔记录，未覆盖或删除。');}return raw;}
function keepOriginal(value:any){readOriginal();const p=qualityCommand(value,owner()),raw=JSON.stringify(p);sessionStorage.setItem(key(),raw);cacheRaw.value=raw;return p;}
function cleanupKnown(){if(busy.value||cacheBlocked.value||!pending.value||!['confirmed','rejected'].includes(pending.value.phase))return false;try{readOriginal();sessionStorage.removeItem(key());cacheRaw.value=null;pending.value=null;cacheError.value='';notice.value='原结果已核对，仅清理本机提示。';return true;}catch(e){cacheError.value=explain(e);return false;}}
function clearPending(value:any){if(busy.value||cacheBlocked.value||!sameQualityPending(value,pending.value))return false;try{const p=qualityCommand(value,owner());pending.value={...p,phase:p.phase==='rejected'?'rejected':'confirmed'};}catch(e){cacheError.value=explain(e);return false;}try{keepOriginal(pending.value);}catch(e){cacheError.value='原结果已知，本机确认状态未写入；仅清理，不重办。 '+explain(e);}return cleanupKnown();}

async function initialize(){clearView();clinics.value=[];manageClinicIds.value=[];error.value='';restoreCache();const current=authScope.begin('initialize');loading.value=true;try{const b=await api('/bootstrap',undefined,current);if(!current())return;clinics.value=b.clinics;manageClinicIds.value=b.manageClinicIds||[];clinic.value=b.clinics.some((c:any)=>c.id===clinic.value)?clinic.value:b.clinics[0]?.id||'';const target=props.returnEntry?qualitySourceEntry(props.returnEntry):null;if(target){if(!b.clinics.some((c:any)=>c.id===target.clinicId))throw Error('当前资料检查范围不包含原诊所。');clinic.value=target.clinicId;year.value=target.year;quarter.value=target.quarter;}if(clinic.value)await refresh();if(current()&&target){await select(target.qualityIssueId);if(current())emit('return-consumed');}}catch(e){if(current())error.value=explain(e);}finally{if(current.active())loading.value=false;}}
watch(identity,()=>{pending.value=null;void initialize();},{flush:'sync'});
function clearHistory(){historyItems.value=[];historyTotal.value=null;historyNext.value=null;historyAsOf.value='';historyLoading.value=false;}
async function refresh(more=false){if(!clinic.value||more&&!next.value)return;const oldId=detail.value?.issue.issue_id;if(!more)clearView();const originalChoice=choice.value,current=viewScope.begin('list');loading.value=true;if(!cacheBlocked.value)error.value='';const params=new URLSearchParams({...Object.fromEntries(Object.entries(filters()).map(([k,v])=>[k,String(v)])),...(more?{cursor:next.value!}:{})});try{const permissions=await api('/bootstrap',undefined,current);if(!current())return;manageClinicIds.value=permissions.manageClinicIds||[];const b=await api('/queue?'+params,undefined,current);if(!current())return;if(more&&b.asOf!==listAsOf.value)throw new ApiError(409,'问题列表查询时点已变化，请重新读取。');items.value=more?[...items.value,...b.items]:b.items;next.value=b.next??null;listTotal.value=b.total??b.items.length;listAsOf.value=b.asOf??'';if(oldId&&choice.value===originalChoice)await select(oldId);}catch(e:any){if(!current())return;if(e.status===409)clearList();error.value=explain(e);}finally{if(current.active())loading.value=false;}}
async function select(id:string){choice.value++;selected.value=id;detail.value=null;source.value=null;mode.value='';preview.value=null;clearHistory();const current=viewScope.begin('detail',()=>JSON.stringify([selected.value,choice.value]));error.value='';try{const r=await api('/'+id+'/view',undefined,current);if(!current())return;detail.value=r;await loadHistory();}catch(e){if(current())error.value=explain(e);}}
async function loadHistory(more=false){if(!detail.value||more&&!historyNext.value)return;const id=detail.value.issue.issue_id,basis=detail.value.basis;if(!more)clearHistory();const current=viewScope.begin('history',()=>JSON.stringify([selected.value,choice.value,detail.value?.issue.issue_id,detail.value?.basis]));historyLoading.value=true;error.value='';const params=new URLSearchParams({...(basis?{basis}:{}),...(more?{cursor:historyNext.value!}:{})});try{const r=await api('/'+id+'/history-page'+(params.size?'?'+params:''),undefined,current);if(!current())return;if(basis&&r.basis!==basis||more&&r.asOf!==historyAsOf.value)throw new ApiError(409,'原问题或历史读取时点已变化，请重新打开。');historyItems.value=more?[...historyItems.value,...r.items]:r.items;historyNext.value=r.next??null;historyTotal.value=r.total??r.items.length;historyAsOf.value=r.asOf??'';}catch(e:any){if(!current())return;if(e.status===409){clearHistory();choice.value++;selected.value='';detail.value=null;source.value=null;mode.value='';}error.value=explain(e);}finally{if(current.active())historyLoading.value=false;}}
function back(){clearHistory();choice.value++;selected.value='';viewScope.begin('detail');detail.value=null;source.value=null;mode.value='';}
function filter(){void refresh();}
async function check(){if(cacheBlocked.value||pending.value||!canManage.value)return;const current=viewScope.begin('scan',scanSignature),input=copy({...filters(),kinds:kinds.value}),signature=scanSignature();busy.value=true;error.value='';preview.value=null;try{const r=await api('/preview',input,current);if(current())preview.value={...r,signature,input};}catch(e){if(current())error.value=explain(e);}finally{if(current.active())busy.value=false;}}

function retryOriginal(p:any){if(busy.value||cacheBlocked.value||!sameQualityPending(p,pending.value)||p.phase&&p.phase!=='pending')return;return send(p.path,p.body,p.label);}
function recoveryDenied(code:number){loseAccess();error.value='当前资料检查读取权限已失效，请重新核对。';if(code===401)emit('unauthorized');}

async function send(path:string,body:any,label:string){if(cacheBlocked.value||busy.value||pending.value?.phase&&pending.value.phase!=='pending')return;let p:any;const previous=pending.value,retry=!!previous;error.value='';notice.value='';try{p=qualityCommand({path,body,label},owner());if(previous&&!sameQualityPending(previous,p))throw Error('已有另一笔原请求，未发送。');p=keepOriginal(p);pending.value=p;cacheError.value='';}catch(e){pending.value=previous;cacheError.value='原请求未能完整存入本机，本次未发送。 '+explain(e);error.value=cacheError.value;return;}
 const current=viewScope.capture(),own=authScope.capture();busy.value=true;let result:any;try{result=await api(p.path,p.body,current);if(!current())return;validQualitySaved(p,result);}catch(e:any){if(!current())return;error.value=explain(e);if(!retry&&e instanceof ApiError&&e.status>=400&&e.status<500){pending.value={...p,phase:'rejected'};mode.value='';busy.value=false;clearPending(pending.value);}else{pending.value=p;mode.value='';error.value='提交结果暂不能确认，请保留原请求，先只读核实。';}return;}finally{if(current())busy.value=false;}
 if(!current())return;pending.value={...p,phase:'confirmed'};clearPending(pending.value);mode.value='';preview.value=null;const savedNotice=result.repeated?'原提交已核实，未重复办理。':label,savedFilters=JSON.stringify(filters());notice.value=savedNotice;if(path==='/manual')await select(result.id);if(!own()||JSON.stringify(filters())!==savedFilters)return;await refresh();if(own()&&JSON.stringify(filters())===savedFilters)notice.value=savedNotice;
}

function saveScan(){if(cacheBlocked.value||pending.value||busy.value||!preview.value||preview.value.signature!==scanSignature())return;return send('/scan',{requestId:crypto.randomUUID(),...copy(preview.value.input),token:preview.value.token},'检查结果已保存；同一未解决问题不会重复创建。');}
function open(kind:string){if(cacheBlocked.value||pending.value||busy.value||!canManage.value||kind!=='manual'&&!detail.value)return;clearSourceChoices();sourceTerm.value='';formEpoch.value++;sourceEpoch.value++;error.value='';mode.value=kind;source.value=null;form.value={kind,role:detail.value?.issue.responsible_role||'诊所管理人员',note:'',decision:'unresolved',blank:'',actualChecked:false,sourceKind:'expense',sourceId:'',severity:'noncritical'};}
async function findSources(more=false){if(mode.value!=='manual'||busy.value||pending.value||cacheBlocked.value||more&&!sourceNext.value)return;if(!more){clearSourceChoices();source.value=null;form.value.sourceId='';}const current=viewScope.begin('sourceChoices',sourceChoiceSignature),params=new URLSearchParams({...Object.fromEntries(Object.entries(filters()).map(([k,v])=>[k,String(v)])),kind:form.value.sourceKind,term:sourceTerm.value,...(more?{cursor:sourceNext.value!}:{})});sourceLoading.value=true;error.value='';try{const r=await api('/source-choices?'+params,undefined,current);if(!current())return;if(more&&r.asOf!==sourceAsOf.value)throw new ApiError(409,'来源读取时点已变化，请重新查询。');sourceChoices.value=more?[...sourceChoices.value,...r.items]:r.items;sourceTotal.value=r.total;sourceNext.value=r.next??null;sourceAsOf.value=r.asOf;}catch(e:any){if(!current())return;if(e.status===409){clearSourceChoices();source.value=null;form.value.sourceId='';}error.value=explain(e);}finally{if(current.active())sourceLoading.value=false;}}
function chooseSource(item:any){if(mode.value!=='manual'||busy.value||pending.value||cacheBlocked.value)return;const chosen=sourceChoices.value.find(x=>x.id===item.id&&x.token===item.token);if(!chosen)return;if(form.value.sourceId!==chosen.id)form.value.note='';form.value.sourceId=chosen.id;source.value={...copy(chosen),signature:sourceSignature()};}
async function inspect(){if(mode.value!=='manual'||cacheBlocked.value)return;const signature=sourceSignature(),current=viewScope.begin('source',sourceSignature),params=new URLSearchParams({clinicId:clinic.value,kind:form.value.sourceKind,id:form.value.sourceId});source.value=null;error.value='';try{const r=await api('/source?'+params,undefined,current);if(current())source.value={...r,signature};}catch(e){if(current())error.value=explain(e);}}
function save(){if(cacheBlocked.value||busy.value||pending.value||!canManage.value)return;if(mode.value==='manual'){if(!source.value||source.value.signature!==sourceSignature())return;return send('/manual',{requestId:crypto.randomUUID(),...filters(),kind:source.value.kind,sourceId:source.value.id,sourceToken:source.value.token,severity:form.value.severity,role:form.value.role,note:form.value.note},'人工核查事项已保存。');}if(!detail.value||mode.value==='recheck'&&!form.value.actualChecked)return;return send('/'+detail.value.issue.issue_id+'/actions',{requestId:crypto.randomUUID(),version:Number(detail.value.issue.row_version),sourceToken:detail.value.source.token,kind:mode.value,role:mode.value==='assign'?form.value.role:null,note:form.value.note,decision:mode.value==='recheck'?form.value.decision:null,blank:form.value.blank||null,actualChecked:form.value.actualChecked},'本次处理经过已保存，复查结论按实际原记录核验。');}
function close(){if(!busy.value&&!pending.value){clearSourceChoices();formEpoch.value++;sourceEpoch.value++;mode.value='';source.value=null;}}
onMounted(initialize);defineExpose({refresh});
</script>

<template><div class="quality-workspace">
 <div v-if="cacheError" class="b-alert error" role="alert">{{cacheError}} <button class="b-button outline small" :disabled="busy" @click="restoreCache">重读原请求</button></div><div v-if="notice" class="b-alert success" role="status">{{notice}}</div><div v-if="error&&!mode" class="b-alert error" role="alert">{{error}}</div><QualityRecovery v-if="pending" :staff="staff" :pending="pending" :busy="busy" @clear="clearPending" @retry="retryOriginal" @access-lost="recoveryDenied(403)" @unauthorized="recoveryDenied(401)"/>
 <div class="quality-filters"><label>所属诊所<select v-model="clinic" :disabled="cacheBlocked||busy||loading||!!pending" @change="filter"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>年份<input v-model.number="year" :disabled="cacheBlocked||busy||loading||!!pending" type="number" min="2020" max="2100" @change="filter"/></label><label>自然季度<select v-model.number="quarter" :disabled="cacheBlocked||busy||loading||!!pending" @change="filter"><option v-for="n in 4" :key="n" :value="n">第{{n}}季度</option></select></label></div>
 <p v-if="!canManage" class="b-alert">当前仅可查看资料问题及历史；检查与复查需要维护权限。</p><template v-if="!detail"><section v-if="canManage" class="b-card quality-block"><div class="quality-head"><div><h2>检查业务资料</h2><p>检查只发现和跟踪问题，补正由对应岗位回原业务办理。</p></div><button class="b-button outline" :disabled="cacheBlocked||busy||loading||!!pending||!kinds.length" @click="check"><Search :size="17"/>预览检查</button></div><div class="quality-options"><label v-for="(name,k) in names" :key="k" class="b-checkbox"><input v-model="kinds" :disabled="cacheBlocked||busy||loading||!!pending" type="checkbox" :value="k" @change="preview=null"/><span>{{name}}</span></label></div><div v-if="preview" class="quality-preview"><h3>{{preview.period}} · 检查发现{{preview.items.length}}项</h3><p v-if="!preview.items.length">本批规则未发现问题，不代表所有业务及关联都已完整。</p><article v-for="p in preview.items" :key="p.locator" class="quality-row"><strong>{{p.category}} · {{short(p.id)}}</strong><span>{{p.severity==='critical'?'交易关键':'非关键病历'}} · 原版{{p.sourceVersion}} · {{p.role}}</span></article><button class="b-button" :disabled="cacheBlocked||busy||loading||!!pending" @click="saveScan">保存检查问题</button></div></section>
 <section class="b-card quality-block"><div class="quality-head"><div><h2>问题跟踪</h2><p>已通知不等于已解决；复查保留实际原记录版本和依据。</p></div><button class="b-button outline" :disabled="busy||loading" @click="refresh()">重新读取问题</button><button v-if="canManage" class="b-button outline" :disabled="cacheBlocked||busy||loading||!!pending" @click="open('manual')"><Plus :size="17"/>人工核查事项</button></div><p v-if="listTotal!==null">已载入 {{items.length}} / {{listTotal}} 项 · 同一查询时点 {{full(listAsOf)}}</p><article v-for="i in items" :key="i.issue_id" class="quality-row"><div><strong>{{i.category}} · {{states[i.resolution_state]||i.resolution_state}}</strong><p>{{i.severity==='critical'?'交易关键':'非关键'}} · {{i.responsible_role}} · {{i.source_locator}}<span v-if="i.sourceAvailable===false"> · 原来源待核对</span></p></div><button class="b-button outline small" :disabled="busy||loading" @click="select(i.issue_id)">{{canManage?'查看与办理':'查看问题'}}</button></article><p v-if="listTotal===0&&!loading">本季尚无已登记问题。</p><p v-if="loading" role="status">正在读取资料问题…</p><button v-if="next" class="b-button outline" :disabled="busy||loading" @click="refresh(true)">加载下一页问题</button></section></template>
 <template v-else><button class="f-text quality-back" @click="back"><ArrowLeft :size="16"/>返回问题列表</button><section class="b-card quality-block"><div class="quality-head"><div><h2>{{detail.issue.category}}</h2><p>{{detail.issue.period_note}} · {{detail.issue.severity==='critical'?'交易关键':'非关键'}} · {{detail.issue.responsible_role}}</p></div><span class="b-pill" :class="detail.issue.resolution_state==='open'?'':'active'">{{states[detail.issue.resolution_state]||detail.issue.resolution_state}}</span></div><p class="quality-locator">来源：{{detail.issue.source_locator}}</p><section v-if="sourceGuide" class="quality-origin-guide"><strong>补正负责岗位：{{sourceGuide.role}}</strong><p>{{sourceGuide.path}}<br/>{{sourceGuide.text}}</p><button v-if="detail.source.kind==='issue'&&staff.functions?.includes('stock.read')" class="b-button outline small" :disabled="busy||loading||!!pending||!!mode" @click="openOriginalSource">打开原领用台账</button><p v-else-if="detail.source.kind==='issue'">当前账号没有库存查看入口，请由物资管理人员核对原领用。</p><template v-if="detail.source.kind==='expense'"><label>费用来源编号（供财务定位）<input :value="detail.source.id" readonly/></label><p>交接所属诊所和此编号，财务在“季度业绩核算 → 运营费用 → 按编号定位原费用”中核对。</p><button v-if="staff.functions?.includes('expense.manage')" class="b-button outline small" :disabled="busy||loading||!!pending||!!mode" @click="openOriginalExpense">打开原费用</button></template><template v-if="detail.source.kind==='record'"><label>病历来源编号（供医护定位）<input :value="detail.source.id" readonly/></label><p>交接所属诊所和此编号，由负责或参与本次就诊的医护在“诊疗与收费 → 按编号定位原病历”中核对。</p><button v-if="staff.functions?.includes('clinical.read')" class="b-button outline small" :disabled="busy||loading||!!pending||!!mode" @click="openOriginalRecord">打开原病历</button></template></section><p>当前来源第{{detail.source.version}}版 · {{detail.source.date}} · {{detail.source.missing?'本批规则仍提示待补':'本批必需资料规则已满足，仍须人工复查'}}</p><p v-if="detail.issue.handling_note">处理事项：{{detail.issue.handling_note}}</p><p v-if="detail.issue.notification_note">最近通知：{{detail.issue.notification_note}}</p><p v-if="detail.issue.recheck_conclusion">最近复查：{{detail.issue.recheck_conclusion}}<br/>{{full(detail.issue.rechecked_at)}}</p><p v-if="detail.issue.reasonable_blank">合理空项解释：{{detail.issue.reasonable_blank}}</p><div v-if="canManage" class="quality-actions"><button class="b-button outline" :disabled="cacheBlocked||busy||loading||!!pending" @click="open('assign')">调整责任岗位</button><button class="b-button outline" :disabled="cacheBlocked||busy||loading||!!pending" @click="open('notify')">记录实际通知</button><button class="b-button outline" :disabled="cacheBlocked||busy||loading||!!pending" @click="open('handle')">记录处理经过</button><button class="b-button" :disabled="cacheBlocked||busy||loading||!!pending" @click="open('recheck')"><ClipboardCheck :size="17"/>复查原记录</button></div></section><section class="b-card quality-block"><div class="quality-head"><h2>处理与复查历史</h2><button class="b-button outline small" :disabled="historyLoading||busy" @click="loadHistory()">重新读取历史</button></div><p v-if="historyTotal!==null">已载入 {{historyItems.length}} / {{historyTotal}} 项 · 同一查询时点 {{full(historyAsOf)}}</p><p v-if="historyLoading" role="status">正在读取处理历史…</p><article v-for="a in historyItems" :key="a.issue_action_id" class="quality-row history"><strong>{{actions[a.action_kind]||a.action_kind}} · {{a.employee_name}}</strong><small>{{full(a.occurred_at)}}<span v-if="adoptedVersion(a)"> · 当次来源第{{adoptedVersion(a)}}版</span></small><p>{{a.action_conclusion}}</p></article><button v-if="historyNext" class="b-button outline" :disabled="historyLoading||busy" @click="loadHistory(true)">继续加载处理历史</button></section></template>
 <div v-if="mode" class="b-backdrop"><form class="b-dialog quality-dialog" role="dialog" aria-modal="true" @submit.prevent="save"><button type="button" class="b-close" aria-label="关闭资料办理" :disabled="cacheBlocked||busy||loading||!!pending" @click="close"><X :size="21"/></button><div class="b-eyebrow">DATA QUALITY</div><h2>{{mode==='manual'?'登记人工核查事项':actions[mode]}}</h2><div v-if="error" class="b-alert error" role="alert">{{error}}</div>
 <template v-if="mode==='manual'">
 <p class="b-help">查选本诊所、本季度的原记录，再明确选择一项；这里只显示编号、日期、版本和待补状态。</p>
 <div class="b-two-fields"><label>来源类别<select v-model="form.sourceKind"><option v-for="(name,k) in names" :key="k" :value="k">{{name}}</option></select></label><label>来源编号线索（可留空）<input v-model="sourceTerm" maxlength="100" @keydown.enter.prevent="findSources()"/></label></div>
 <button type="button" class="b-button outline" :disabled="sourceLoading||busy||!!pending" @click="findSources()">{{sourceLoading?'正在查询来源…':'查询本季来源'}}</button>
 <p v-if="sourceTotal!==null">已载入 {{sourceChoices.length}} / {{sourceTotal}} 项 · 同一查询时点 {{full(sourceAsOf)}}</p><p v-else-if="!sourceLoading">条件已就绪，请查询并选择来源。</p>
 <div class="quality-source-choices"><article v-for="s in sourceChoices" :key="s.id" class="quality-row"><div><strong>{{s.date}} · 第{{s.version}}版</strong><p>{{s.id}}</p><small>{{s.missing?'本批规则提示待补':'本批必需资料规则已满足'}}</small></div><button type="button" class="b-button outline small" :disabled="busy||!!pending||sourceLoading" @click="chooseSource(s)">{{source?.id===s.id?'已选择此来源':'选择此来源'}}</button></article></div>
 <p v-if="sourceTotal===0">本季没有匹配来源，请核对类别、编号或所属季度。</p><button v-if="sourceNext" type="button" class="b-button outline" :disabled="sourceLoading||busy||!!pending" @click="findSources(true)">继续加载来源</button>
 <p v-if="source" class="quality-selected" role="status">已选 {{names[source.kind]}} · {{source.date}} · 第{{source.version}}版<br/>{{source.id}}<br/>仅登记核查事项；补正请由对应岗位回原业务办理。</p>
 <label>关键程度<select v-model="form.severity"><option value="noncritical">非关键人工事项</option><option value="critical">交易关键事项</option></select></label></template>
 <label v-if="mode==='assign'||mode==='manual'">负责岗位<select v-model="form.role"><option v-for="r in roles" :key="r">{{r}}</option></select></label>
 <template v-if="mode==='recheck'"><label>复查结论<select v-model="form.decision"><option value="unresolved">仍未解决，继续跟踪</option><option value="corrected">已核实补正</option><option v-if="detail.issue.category==='人工核查事项'" value="justified_blank">已核实为合理空项</option></select></label><label v-if="form.decision==='justified_blank'">合理空项解释<textarea v-model="form.blank" rows="2" required maxlength="2000"/></label><label class="b-checkbox"><input v-model="form.actualChecked" type="checkbox" required/><span>已实际查阅并核实对应原记录，本次结论和依据属实。</span></label></template>
 <label>{{mode==='recheck'?'复查实际依据与结论':mode==='notify'?'实际通知对象、方式、时间与内容':mode==='assign'?'岗位调整原因与具体处理事项':'实际核查或处理事项'}}<textarea v-model="form.note" required rows="4" maxlength="2000"/></label><p class="b-help">这里不代写病历、改库存或费用，也不会拨号、发送消息。通知仅记录已经发生的事实。</p><p v-if="pending" class="b-help">原提交结果待核实，请关闭办理后使用页面上的只读核实。</p><button v-else class="b-button full" :disabled="cacheBlocked||busy||(mode==='manual'&&!source)">{{busy?'正在核验…':'确认保存本次记录'}}</button></form></div>
</div></template>
<style scoped>
.quality-block{padding:26px;margin:20px 0}.quality-block h2{margin:0 0 8px;font-size:21px}.quality-block p{font-size:14px;color:#728478;line-height:1.8;overflow-wrap:anywhere}.quality-filters{display:flex;gap:16px;flex-wrap:wrap;margin:22px 0}.quality-filters label:first-child{min-width:230px;flex:1}.quality-filters input{width:110px}.quality-head,.quality-row{display:flex;justify-content:space-between;align-items:center;gap:18px}.quality-row{padding:18px 0;border-bottom:1px solid #e1e9df;font-size:14px}.quality-row>div{min-width:0}.quality-row span,.quality-row small{color:#7b8d78;font-size:13px}.quality-options,.quality-actions{display:flex;flex-wrap:wrap;gap:15px;margin:20px 0}.quality-options .b-checkbox{margin:0}.quality-preview{padding:20px;background:#f3f7ee;border-radius:12px}.quality-preview>.b-button{margin-top:20px}.quality-locator{padding:14px;background:#f4f7f2;border-radius:8px}.quality-back{display:inline-flex;align-items:center;gap:8px;margin-top:20px}.history{align-items:start;flex-direction:column;gap:6px}.history p{margin:2px 0}.quality-dialog.b-dialog{width:min(680px,calc(100vw - 36px));max-width:680px}.quality-dialog>label{margin:18px 0}.quality-dialog .b-checkbox{align-items:start}.quality-dialog textarea{resize:vertical}.quality-row .b-button{flex-shrink:0}@media(max-width:760px){.quality-block{padding:18px}.quality-head,.quality-row{align-items:start;flex-direction:column;gap:12px}.quality-filters{gap:12px}.quality-filters label:first-child{flex-basis:100%}.quality-dialog.b-dialog{width:calc(100vw - 28px)}}
.quality-source-choices{max-height:290px;overflow:auto;margin:12px 0}.quality-source-choices .quality-row{padding:12px 4px;align-items:start}.quality-source-choices p{margin:4px 0;overflow-wrap:anywhere}.quality-selected{padding:12px;background:#f3f7ee;border-radius:8px;overflow-wrap:anywhere}
.quality-origin-guide{padding:16px;background:#f3f7ee;border-radius:10px;margin:16px 0}
</style>






